"""Generate dbt ``_sources.yml`` from declarative asset_property YAML."""

from __future__ import annotations

import logging
from collections import defaultdict
from collections.abc import Iterable
from pathlib import Path
from typing import Any

import yaml

from ndr_lakehouse.asset_property.schema_validator import (
    AssetConfig,
    discover_asset_configs,
)

logger = logging.getLogger(__name__)

_SOURCE_HEADER_TEMPLATE = """\
# AUTO-GENERATED FILE. DO NOT EDIT.
# Generated by ndr_lakehouse.orchestration.dbt_source_sync from
# {source_label}.
"""


def build_sources_document(configs: Iterable[AssetConfig]) -> dict[str, Any]:
    """Build the dbt sources document (pure function)."""

    grouped: dict[tuple[str, str], list[AssetConfig]] = defaultdict(list)
    for config in configs:
        catalog = config.catalog_properties
        grouped[(catalog.catalog_name, catalog.schema_name)].append(config)

    schema_counts: dict[str, int] = defaultdict(int)
    for _, schema in grouped:
        schema_counts[schema] += 1

    sources: list[dict[str, Any]] = []
    for (catalog_name, schema_name), items in sorted(grouped.items()):
        source_name = (
            schema_name if schema_counts[schema_name] == 1 else f"{catalog_name}_{schema_name}"
        )
        tables = []
        for config in sorted(items, key=lambda item: item.catalog_properties.table_name):
            catalog = config.catalog_properties
            tables.append(
                {
                    "name": catalog.table_name,
                    "description": config.description
                    or f"Bronze Iceberg table {catalog.full_table_name}",
                    "meta": {
                        "dagster": {
                            "asset_key": [
                                catalog.catalog_name,
                                catalog.schema_name,
                                catalog.table_name,
                            ]
                        }
                    },
                }
            )
        sources.append(
            {
                "name": source_name,
                "description": (f"Unity Catalog Iceberg schema {catalog_name}.{schema_name}"),
                "schema": schema_name,
                "tables": tables,
            }
        )
    return {"version": 2, "sources": sources}


def generate_sources_yaml(
    configs: Iterable[AssetConfig],
    output_path: str | Path,
    *,
    source_label: str = "the configured asset directory",
) -> Path:
    """Write the dbt sources document and return its path."""

    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    document = build_sources_document(configs)
    rendered = yaml.safe_dump(
        document,
        sort_keys=False,
        default_flow_style=False,
        allow_unicode=True,
    )
    header = _SOURCE_HEADER_TEMPLATE.format(source_label=source_label)
    path.write_text(f"{header}\n{rendered}", encoding="utf-8")
    logger.info("Synchronised dbt sources -> %s", path)
    return path


def sync_dbt_sources(
    asset_dir: str | Path,
    output_path: str | Path,
    *,
    source_label: str,
) -> Path:
    """Discover YAML configs and regenerate the dbt sources file."""

    configs = discover_asset_configs(asset_dir)
    return generate_sources_yaml(configs, output_path, source_label=source_label)
